import argparse, pandas as pd
ap=argparse.ArgumentParser(); ap.add_argument("--small",required=True); ap.add_argument("--large",required=True); ap.add_argument("--violations",nargs="+",required=True); ap.add_argument("--out",required=True); a=ap.parse_args(); s=pd.read_csv(a.small); l=pd.read_csv(a.large); keys=["image_id","file_name","class"]; m=s.merge(l,on=keys,suffixes=("_small","_large")); v=m[m["class"].isin(a.violations)].copy(); agg=v.groupby(["image_id","file_name"],as_index=False).agg(gt=("gt_small","sum"),fn_small=("fn_small","sum"),fn_large=("fn_large","sum"),tp_small=("tp_small","sum"),tp_large=("tp_large","sum")); agg["recovered_violations"]=(agg["fn_small"]-agg["fn_large"]).clip(lower=0); agg["oracle_escalate"]=(agg["recovered_violations"]>0).astype(int); agg.to_csv(a.out,index=False); print(agg["oracle_escalate"].value_counts().to_dict())
